/*
 * The length bytes at offset in the data of the protocol at proto_index, or
 * NULL when the captured packet does not hold them all.
 */
static const uint8_t *quic_example_bytes(const ipacket_t *packet, mmt_proto_index_t proto_index, int64_t offset, int64_t length)
{
    int64_t caplen = (int64_t) packet->p_hdr->caplen;
    int64_t start = (int64_t) get_packet_offset_at_index(packet, proto_index);

    if (start < 0 || offset < 0 || length < 0 || offset > caplen || length > caplen) {
        return NULL;
    }
    start += offset;
    if (start > caplen - length) {
        return NULL;
    }
    return &packet->data[start];
}

/* An unsigned integer of width bytes (1 to 8), in network byte order (big-endian). */
static uint64_t quic_example_read(const uint8_t *p, unsigned width)
{
    uint64_t value = 0;
    unsigned i;

    for (i = 0; i < width; i++) {
        value = (value << 8) | p[i];
    }
    return value;
}

